import{_ as n,o as i,c as t,a5 as h}from"./chunks/framework.CsGesDJn.js";const s=JSON.parse('{"title":"Giai đoạn 1 — mô hình và phạm vi Campaign","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/phase-1-design/spec.md","filePath":"feature/media-package-campaign/phase-1-design/spec.md"}'),e={name:"feature/media-package-campaign/phase-1-design/spec.md"};function o(c,a,r,g,l,p){return i(),t("div",null,[...a[0]||(a[0]=[h('<h1 id="giai-đoan-1-—-mo-hinh-va-pham-vi-campaign" tabindex="-1">Giai đoạn 1 — mô hình và phạm vi Campaign <a class="header-anchor" href="#giai-đoan-1-—-mo-hinh-va-pham-vi-campaign" aria-label="Permalink to &quot;Giai đoạn 1 — mô hình và phạm vi Campaign&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Thuộc tính</th><th>Giá trị</th></tr></thead><tbody><tr><td>Ngày</td><td>2026-10-08</td></tr><tr><td>FR / Jira</td><td>3.5.5 / DA-947; 3.5.6 / DA-948; tích hợp E51</td></tr><tr><td>Trạng thái</td><td>Hoàn thành thiết kế giai đoạn 1; A1–A3 được người dùng xác nhận 2026-10-08; chưa implementation</td></tr><tr><td>Phạm vi</td><td>Thiết kế và hợp đồng tích hợp; không viết/chạy migration hay thay application code</td></tr></tbody></table><h2 id="objective-va-user-story" tabindex="-1">Objective và user story <a class="header-anchor" href="#objective-va-user-story" aria-label="Permalink to &quot;Objective và user story&quot;">​</a></h2><p>Manager lập một kế hoạch triển khai từ Package đã chốt trong Workspace; Client xem, góp ý và duyệt; Manager triển khai thành backlog rồi chủ động kết thúc Campaign. Thiết kế phải giữ dữ liệu và khả năng sử dụng editor hiện có khi Task chuyển về Mongo V2.</p><h2 id="quyet-đinh-ba-đa-chot" tabindex="-1">Quyết định BA đã chốt <a class="header-anchor" href="#quyet-đinh-ba-đa-chot" aria-label="Permalink to &quot;Quyết định BA đã chốt&quot;">​</a></h2><ul><li>AC1: một Workspace có tối đa một Campaign, kể cả draft/completed; chiến dịch khác dùng Workspace khác, Owner có tính năng Duplicate Workspace ở giai đoạn 5.</li><li>AC2: nguồn phạm vi là snapshot của WorkspaceMediaPackage APPROVED, không lấy lại nội dung catalogue có thể bị Owner sửa sau đó.</li><li>AC3: Client góp ý, Manager sửa. Mỗi thay đổi nội dung thực sự tăng contentVersion, làm mất hiệu lực cả hai approval. Approval gắn với đúng phiên bản được xem.</li><li>AC4: chỉ triển khai sau khi cả Agency và Client duyệt. Nội dung đã chốt bất biến; trạng thái vận hành, deployment và completion được quản lý riêng.</li><li>AC5: Task dùng Mongo V2. Task mới do Campaign sinh ra bắt đầu BACKLOG, chưa giao người thực hiện/QC; nội dung chuyên biệt thuộc E51 hoặc task mở rộng được phân công.</li><li>AC6: Manager chủ động mark completed từ IN_PROGRESS; được phép khi còn Task chưa COMPLETED nhưng phải ghi lý do. Lưu actor/time/reason; giữ nguyên trạng thái và khả năng tiếp tục xử lý Task con theo quyền/workflow của Task.</li><li>AC7: retry/concurrent deploy không tạo trùng hoặc reset Task đang được thực hiện.</li><li>AC8: mọi thao tác phải xác minh Workspace thực tế và vai trò hiện tại; không dựa riêng vào Workspace/role được lưu trong JWT hoặc lựa chọn cũ trên UI.</li></ul><h2 id="quyet-đinh-ba-trong-giai-đoan-1-đa-xac-nhan" tabindex="-1">Quyết định BA trong giai đoạn 1 (đã xác nhận) <a class="header-anchor" href="#quyet-đinh-ba-trong-giai-đoan-1-đa-xac-nhan" aria-label="Permalink to &quot;Quyết định BA trong giai đoạn 1 (đã xác nhận)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Nội dung</th><th>Quyết định người dùng</th><th>Ảnh hưởng</th></tr></thead><tbody><tr><td>A1</td><td>Mô hình tính sản lượng</td><td>Tổng cho cả gói; không có hạn mức theo tháng trong đợt này</td><td>Schema Package, conversion, planning form</td></tr><tr><td>A2</td><td>Event/press có Task workflow không?</td><td>Thêm EVENT_PLAN và PRESS_RECOMMENDATION trong tasks chung, collection riêng chứa nội dung</td><td>Enum/validator/views/approval và phối hợp E51</td></tr><tr><td>A3</td><td>Complete khi còn Task chưa xong?</td><td>Cho phép, bắt buộc lý do; giữ nguyên trạng thái từng Task</td><td>Complete API/UI và test</td></tr></tbody></table><p>Workshop dùng SURVEY cho khảo sát và khả năng Meet gắn Task theo E51-08d; không giả danh Workshop thành LIVESTREAM. Hợp đồng tích hợp được ghi ở plan.md, cần phối hợp chủ E51 trước khi thay implementation chuyên biệt. Task types mới không mở rộng scope sang hậu cần/vận hành sự kiện, booking hoặc tự đăng lên báo.</p><p>Sản lượng của mỗi deliverable là tổng cho cả Package; duration chỉ mô tả thời gian, không nhân sản lượng theo tháng. offeringModel cũ giữ để đọc dữ liệu legacy, không còn quyết định luồng Campaign mới. Snapshot RETAINER đã chốt không tự chuyển đổi; phải xử lý riêng trước khi cho lập Campaign theo quy tắc tổng mới.</p><h2 id="ui-ux-muc-tieu" tabindex="-1">UI/UX mục tiêu <a class="header-anchor" href="#ui-ux-muc-tieu" aria-label="Permalink to &quot;UI/UX mục tiêu&quot;">​</a></h2><ul><li>Một mục Campaign trong Workspace. Chưa có: Manager tạo từ Package approved, Client thấy trạng thái chờ kế hoạch. Đã có: xem Campaign, không có nút tạo thứ hai.</li><li>Các phần: phạm vi Package, chiến lược, timeline, sản phẩm bàn giao, đầu việc, góp ý/phiên bản/duyệt và tiến độ triển khai.</li><li>Lưu nháp cho phép kế hoạch chưa đầy đủ; trước approve kiểm tra đủ thông tin triển khai. Client góp ý không tự thay nội dung Campaign.</li><li>Trạng thái UI: loading, chưa có Package, Package chưa chốt, chưa có Campaign, draft, approval một phía, approved, deploying/failed, in progress, completed, conflict version, forbidden và lỗi kết nối.</li><li>Text mới dùng key vi/en song song trong namespace campaign: overview, plan, workItems, feedback, approval, deployment, completion, errors. Dùng semantic theme tokens, light/dark và responsive theo quy tắc dự án.</li></ul><h2 id="loi-va-edge-cases" tabindex="-1">Lỗi và edge cases <a class="header-anchor" href="#loi-va-edge-cases" aria-label="Permalink to &quot;Lỗi và edge cases&quot;">​</a></h2><ul><li>Package chưa chốt: 409 PACKAGE_NOT_APPROVED; Campaign đã có: 409 conflict và ID hiện có.</li><li>Sai Workspace/quyền: 403 hoặc 404 theo convention, không lộ dữ liệu Workspace khác.</li><li>Version cũ: 409, yêu cầu tải lại; không tự approve phiên bản mới thay người dùng.</li><li>Chưa đủ hai approval/plan chưa đầy đủ: không deploy/approve, trả lỗi field/state rõ.</li><li>Dữ liệu prototype có nhiều Campaign: báo danh sách xung đột, không tự xóa/gộp.</li><li>Catalogue đổi, retry sau crash, mất kết nối Mongo hoặc editor lookup fail: fail closed, giữ dữ liệu đã ghi và cho phép retry theo contract.</li><li>Chi tiết API/data model và các điều kiện tương thích ở plan.md.</li></ul><h2 id="definition-of-done-cua-giai-đoan-1" tabindex="-1">Definition of done của giai đoạn 1 <a class="header-anchor" href="#definition-of-done-cua-giai-đoan-1" aria-label="Permalink to &quot;Definition of done của giai đoạn 1&quot;">​</a></h2><ol><li>A1–A3 đã được người dùng xác nhận và ghi lại ở trên.</li><li>Schema Campaign/work item, API, state/version và quyền đã thống nhất.</li><li>Có phương án Task/editor, migration dữ liệu cũ và checklist kiểm chứng; chưa chạy migration.</li><li>spec/plan/task/test, roadmap và FR liên quan đồng bộ; ghi rõ task/ownership cần phối hợp.</li><li>Không đánh dấu giai đoạn 2–4 hoặc Jira DA-947/948 Done chỉ vì hoàn thành thiết kế.</li></ol><p>Ngoài phạm vi: Duplicate Workspace implementation, specialist authoring forms, booking/phát sóng/hậu cần sự kiện, billing, Campaign Addendum, seed tài khoản mới.</p><p>Nguồn: <a href="./../../../ba/04-media-package-campaign.html">BA</a>, <a href="./../implementation-roadmap.html">roadmap</a>, <a href="./../campaign-delivery-plan.html">delivery plan</a>.</p>',18)])])}const m=n(e,[["render",o]]);export{s as __pageData,m as default};
